/**
 * Service layer for media operations
 *
 * Provides a bridge between clients and the underlying network/cache layers.
 * Handles fetching, creating, updating, and deleting media. `create_media`
 * is exposed here for progress-aware upload via `RequestContext` threading;
 * `update_media` and `delete_media_permanently` are cache-aware wrappers
 * around the underlying `MediaRequestExecutor`.
 *
 * # Metadata Sync Infrastructure
 *
 * The service provides access to metadata-first sync infrastructure:
 * - Entity state tracking via `EntityStateStore` associated functions
 * - Database-backed list metadata via `metadata_service`
 *
 * Collections get read-only access via reader methods. This ensures cross-collection
 * consistency when multiple collections share the same underlying entities.
 */
public protocol MediaServiceProtocol: AnyObject, Sendable {
    
    /**
     * Get the total count of media for this site
     */
    func countEditContext() throws  -> Int64
    
    /**
     * Create a new media item via REST POST and upsert it into the cache.
     *
     * Mirrors `PostService::create_post`. The `context` parameter threads a
     * `RequestContext` from Swift (via `WordPressAPI::fulfill(progress:withApiCall:)`)
     * through to the generated `MediaRequestExecutor::create_cancellation`,
     * which routes through `perform_upload(request, context.clone())`. That's
     * what enables byte-level upload progress and request-level cancellation
     * on the Swift side without any new Rust-side progress infrastructure.
     */
    func createMedia(params: MediaCreateParams, context: RequestContext?) async throws  -> MediaWithEditContext
    
    /**
     * Create a metadata-first media collection with edit context
     *
     * Returns a collection that uses a two-phase sync strategy:
     * 1. Fetch lightweight metadata (id + modified_gmt) to define list structure
     * 2. Selectively fetch full data for missing or stale items
     */
    func createMediaMetadataCollectionWithEditContext(filter: MediaListFilter, perPage: UInt32)  -> MediaMetadataCollectionWithEditContext
    
    /**
     * Delete a media item by its EntityId
     */
    func deleteByEntityId(entityId: EntityId) throws  -> UInt64
    
    /**
     * Delete a media item by its WordPress media ID
     */
    func deleteByMediaId(mediaId: MediaId) throws  -> UInt64
    
    /**
     * Permanently delete a media item via the REST API and remove it from the local cache.
     *
     * REST DELETE on media always passes `force=true` (the server rejects `force=false`),
     * so there is no separate "trash" path.
     */
    func deleteMediaPermanently(mediaId: MediaId) async throws  -> MediaDeleteResponse
    
    /**
     * Get an entity handle using an EntityId
     *
     * Returns an entity that can be used to read media data with full edit context.
     * The entity is lightweight - it doesn't fetch data until you call load_data() on it.
     */
    func getEntityWithEditContext(entityId: EntityId)  -> EntityMediaWithEditContext
    
    /**
     * Shared prefix for every cached edit-context media list key on this site.
     * Used both when constructing a list's `ListKey` and when scrubbing a
     * deleted entity from every media list for the site, so the two paths
     * can't drift apart.
     */
    func mediaListKeyPrefix()  -> String
    
    /**
     * Update a media item via REST POST and upsert it into the cache.
     *
     * Mirrors `PostService::update_post`. Successful HTTP response is
     * upserted into the cache and fanned out via `notify_collections`
     * so live collections refresh their membership without a full reload.
     */
    func updateMedia(mediaId: MediaId, params: MediaUpdateParams) async throws  -> MediaWithEditContext
    
}
