// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfacePasswordTransformer {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfacePasswordTransformer = UniffiVTableCallbackInterfacePasswordTransformer(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypePasswordTransformer.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface PasswordTransformer: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypePasswordTransformer.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface PasswordTransformer: handle missing in uniffiClone")
            }
        },
        encrypt: { (
            uniffiHandle: UInt64,
            password: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> EncryptedPassword in
                guard let uniffiObj = try? FfiConverterTypePasswordTransformer.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.encrypt(
                     password: try FfiConverterTypeDecryptedPassword_lift(password)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterTypeEncryptedPassword_lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypePasswordTransformerError_lower
            )
        },
        decrypt: { (
            uniffiHandle: UInt64,
            password: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> DecryptedPassword in
                guard let uniffiObj = try? FfiConverterTypePasswordTransformer.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.decrypt(
                     password: try FfiConverterTypeEncryptedPassword_lift(password)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterTypeDecryptedPassword_lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypePasswordTransformerError_lower
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfacePasswordTransformer> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfacePasswordTransformer>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitPasswordTransformer() {
    uniffi_wp_mobile_fn_init_callback_vtable_passwordtransformer(UniffiCallbackInterfacePasswordTransformer.vtablePtr)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePasswordTransformer: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<PasswordTransformer>()

    typealias FfiType = UInt64
    typealias SwiftType = PasswordTransformer

    public static func lift(_ handle: UInt64) throws -> PasswordTransformer {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return PasswordTransformerImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: PasswordTransformer) -> UInt64 {
         if let rustImpl = value as? PasswordTransformerImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PasswordTransformer {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: PasswordTransformer, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


