    /**
     * Check if there are more pages to load.
     *
     * Returns:
     * - `None` - Unknown (no metadata loaded or total_pages not provided by API)
     * - `Some(true)` - More pages available
     * - `Some(false)` - On last page
     */
    func hasMorePages()  -> Bool?
    
